# Artificer · Light — eza colours
# Source this from ~/.zshrc. eza reads EZA_COLORS on every invocation, so no
# reload step is needed beyond starting a new shell.
#
# Generated from themes/_palette.json — edit there + re-run build.mjs.
# This is LS_COLORS grammar, not hex: 38;2;R;G;B is an SGR truecolor escape.
# Permission slots match yazi's [status] perm_read / perm_write / perm_exec so
# the two file listers agree.

export EZA_COLORS="di=38;2;64;98;120:ex=38;2;42;90;58:ln=38;2;58;106;104:or=38;2;138;36;24:pi=38;2;160;69;0:so=38;2;90;53;176:bd=38;2;160;69;0:cd=38;2;160;69;0:ur=38;2;122;90;16:uw=38;2;160;69;0:ux=38;2;42;90;58:ue=38;2;42;90;58:gr=38;2;122;90;16:gw=38;2;160;69;0:gx=38;2;42;90;58:tr=38;2;122;90;16:tw=38;2;160;69;0:tx=38;2;42;90;58:su=38;2;138;36;24:sf=38;2;138;36;24:xa=38;2;90;122;138:sn=38;2;32;32;62:sb=38;2;90;122;138:uu=38;2;122;90;16:un=38;2;90;122;138:gu=38;2;122;90;16:gn=38;2;90;122;138:da=38;2;90;122;138:ga=38;2;42;90;58:gm=38;2;160;69;0:gd=38;2;138;36;24:gv=38;2;90;53;176:gt=38;2;58;106;104:xx=38;2;203;184;138"